export interface SyncStageOptions {
    verbose?: boolean;
    force?: boolean;
    silent?: boolean;
    external?: boolean;
}
/**
 * Stage files of a skills to be synced to the robot
 * this doesn't actually do the transport, that's accomplished
 * by either jibo-sync or jibo-rsync.
 * @class SyncStage
 * @param {string} cwd - Directory to sync
 * @param {Object} [options] Optional arguments
 * @param {boolean} [options.force=false] Clean staged folder each time.
 * @param {boolean} [options.verbose=false] Run in verbose mode.
 * @param {boolean} [options.silent=false] Suppress all output messages.
 * @param {boolean} [options.external=false] Fetch dependencies from npm
 */
export default class SyncStage {
    /**
     * Name of the syncignore file
     * @name SyncStage.FILENAME
     * @type {string}
     * @readonly
     * @default '.syncignore'
     */
    static FILENAME: string;
    /**
     * Name of the default staged folder
     * @name SyncStage.FOLDER
     * @type {string}
     * @readonly
     * @default '.staged'
     */
    static FOLDER: string;
    /**
     * The absolute path to the current working directory to sync
     * @name SyncStage#cwd
     * @type {string}
     * @readonly
     */
    cwd: string;
    /**
     * The absolute path to the staged folder
     * @name SyncStage#staged
     * @type {string}
     * @readonly
     */
    staged: string;
    /**
     * Suppress all console messages
     * @name SyncStage#silent
     * @type {boolean}
     * @readonly
     */
    silent: boolean;
    /**
     * Remove the staged folder before starting a new stage
     * @name SyncStage#force
     * @type {boolean}
     * @readonly
     */
    force: boolean;
    /**
     * Run in verbose mode
     * @name SyncStage#verbose
     * @type {boolean}
     * @readonly
     */
    verbose: boolean;
    /**
     * Fetch dependencies from npm to staged directory
     * @name SyncStage#external
     * @type {boolean}
     * @readonly
     */
    external: boolean;
    /**
     * Run the commandline version of SyncStage
     * @method SyncStage.cli
     * @static
     */
    static cli(): void;
    /**
     * Constructor
     */
    constructor(cwd: string, options?: SyncStageOptions);
    /**
     * Begin the staging
     * @method SyncStage#start
     */
    start(): Promise<void>;
    /**
     * Perform install of versioned package
     * @param packageKey - "name@version" package key
     * @param src - src of package to install
     * @param dest - install destination
     */
    private doInstall(packageKey, src, dest);
    /**
     * Determine if package at specific version is resolveable from current directory
     * @param cwd - Directory to search from
     * @param packageName - Name of package to resolve
     * @param version - Specific version of package to resolve
     */
    private isResolvable(cwd, packageName, version);
    /**
     * Execute a commandline.
     * @param {string} command - Command to execute
     * @param {RegExp} cwd - Current working directory
     * @return {Promise} Promise when completed
     */
    private execute(command);
}
